import mujoco, numpy as np, time
def run(mod,seed,timed=False):
    m=mujoco.MjModel.from_xml_path('model_ref.xml'); mod(m)
    d=mujoco.MjData(m)
    rng=np.random.default_rng(seed); d.qpos+=rng.normal(0,0.01,size=d.qpos.shape); mujoco.mj_forward(m,d)
    t=time.perf_counter()
    for _ in range(int(2.0/m.opt.timestep)): mujoco.mj_step(m,d)
    dt=time.perf_counter()-t
    s=np.zeros(mujoco.mj_stateSize(m,mujoco.mjtState.mjSTATE_FULLPHYSICS)); mujoco.mj_getState(m,d,s,mujoco.mjtState.mjSTATE_FULLPHYSICS); return s,dt
def mk(**kw):
    def f(m):
        for k,v in kw.items(): setattr(m.opt,k,v)
    return f
cfg={'tol1e-12':mk(jacobian=0,solver=0,tolerance=1e-12),'tol1e-14':mk(jacobian=0,solver=0,tolerance=1e-14),'tol0':mk(jacobian=0,solver=0,tolerance=0,iterations=20)}
res={k:[[],[]] for k in cfg}; bt=[]
for seed in range(30):
    b,tb=run(mk(),seed); bt.append(tb)
    for k,f in cfg.items():
        s,t=run(f,seed); res[k][0].append(np.abs(s-b).max()); res[k][1].append(t)
print('base t',np.mean(bt))
for k,(e,t) in res.items(): print(k,'maxerr',max(e),'t',np.mean(t),'pct',np.mean(t)/np.mean(bt))
"
